'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isInfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var powf = require( '@stdlib/math/base/special/powf' );
var floorf = require( '@stdlib/math/base/special/floorf' );
var log2 = require( '@stdlib/math/base/special/log2' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var MIN_EXP_SUBNORMAL = require( '@stdlib/constants/float32/min-base2-exponent-subnormal' );


// VARIABLES //

var ZERO = f32( 0.0 );
var TWO = f32( 2.0 );
var ONE = f32( 1.0 );


// MAIN //

/**
* Rounds a single-presicion floating-point number to the nearest power of two toward zero.
*
* @param {number} x - input value
* @returns {number} rounded value
*
* @example
* var v = trunc2f( 3.141592653589793 );
* // returns 2.0
*
* @example
* var v = trunc2f( 13.0 );
* // returns 8.0
*
* @example
* var v = trunc2f( -0.314 );
* // returns -0.25
*/
function trunc2f( x ) {
	var sign;
	var p;

	x = f32( x );

	if (
		isnanf( x ) ||
		isInfinitef( x ) ||
		x === ZERO
	) {
		return x;
	}

	if ( x < ZERO ) {
		x = -x;
		sign = -ONE;
	} else {
		sign = ONE;
	}

	// Solve 2^p = x
	p = f32( log2( x ) );

	// Smallest subnormal
	if ( p === MIN_EXP_SUBNORMAL ) {
		return f32( sign * x );
	}

	// Truncate toward zero
	p = floorf( p );

	return f32( sign * powf( TWO, p ) );
}


// EXPORTS //

module.exports = trunc2f;
